const FREE_OVER = 7500;
const FLAT = 500;

function shippingFor(subtotal) {
  return subtotal >= FREE_OVER ? 0 : FLAT;
}

module.exports = { shippingFor, FREE_OVER, FLAT };
src/money.js
function pct(amountCents, percent) {
  return Math.round(amountCents * percent / 100);
}

module.exports = { pct };
src/coupon.js
function couponValue(subtotal, couponPercent) {
  const capped = Math.max(0, Math.min(100, couponPercent));
  return Math.round(subtotal * capped / 100);
}

module.exports = { couponValue };
src/total.js
const { pct } = require('./money');
const { tax } = require('./tax');

function computeTotal({ subtotal, couponPercent = 0, taxPercent = 0, shipping = 0 }) {
  const discount = pct(subtotal, couponPercent);
  const taxed = tax(subtotal, taxPercent);
  return subtotal - discount + taxed + shipping;
}

module.exports = { computeTotal };
